import type { CopilotResponseSchema } from './copilot-operation'
import { isRecord } from './is-record'

/** Per-run generation contract; an empty description represents an omitted body. */
export const CopilotCommitMessageResponseSchema: CopilotResponseSchema = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    description: { type: 'string' },
  },
  required: ['title', 'description'],
  additionalProperties: false,
}

/** Represents the commit details (title and description) generated by Copilot. */
export interface ICopilotCommitMessage {
  readonly title: string
  readonly description: string
}

export function parseCopilotCommitMessage(
  content: string
): ICopilotCommitMessage {
  let parsed: unknown
  try {
    parsed = JSON.parse(content)
  } catch {
    throw new Error(
      'Copilot returned invalid JSON for commit message generation'
    )
  }

  if (!isRecord(parsed)) {
    throw new Error(
      'Copilot returned an invalid commit message payload: expected an object'
    )
  }

  const title = parsed.title
  if (typeof title !== 'string' || title.trim().length === 0) {
    throw new Error(
      'Copilot returned an invalid commit message payload: "title" must be a non-empty string'
    )
  }

  const description = parsed.description
  if (description === undefined) {
    return {
      title,
      description: '',
    }
  }

  if (typeof description !== 'string') {
    throw new Error(
      'Copilot returned an invalid commit message payload: "description" must be a string when provided'
    )
  }

  return {
    title,
    description,
  }
}
